-- Team Skills Database Seed Data
-- Auto-generated from Inventory.csv
-- Contains hierarchical skill categories and skills (public data)
-- User data is imported separately via /api/admin/sync-skills (private)

-- Skill Categories (hierarchical: Role > Domain > Subdomain)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, parent_id = EXCLUDED.parent_id, level = EXCLUDED.level, sort_order = EXCLUDED.sort_order;

-- Skills (linked to most specific category)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category_id = EXCLUDED.category_id, sort_order = EXCLUDED.sort_order;

SELECT setval('skill_categories_id_seq', 55, true);
SELECT setval('skills_id_seq', 153, true);

-- Demo users (fake data for development/testing)
ON CONFLICT DO NOTHING;
SELECT setval('users_id_seq', 6, true);

-- Demo user skills (fake proficiency data)
ON CONFLICT DO NOTHING;
